#!/usr/bin/env python3
"""Build original, CC0 teaching illustrations. No external documents or API calls."""
from pathlib import Path
import hashlib, html, json
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'public/teaching-examples'
DEST.mkdir(parents=True,exist_ok=True)
examples={}
def text(x,y,value,size=24,attrs=''):
    return f'<text x="{x}" y="{y}" font-size="{size}" {attrs}>{html.escape(value)}</text>'
def rect(x,y,w,h,fill='none',stroke='#334155'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="{stroke}"/>'
def line(x,y,x2,y2):return f'<path d="M{x} {y} L{x2} {y2}" fill="none" stroke="#334155" stroke-width="2"/>'
def page(content,w=720,h=300):
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><rect width="100%" height="100%" fill="white"/><g font-family="Arial, sans-serif" fill="#172033">{content}</g></svg>'
def add(key,title,content,expected,why,bad=None,w=720,h=300,language='markdown'):
    svg=page(content,w,h);file=DEST/(key+'.svg');file.write_text(svg)
    out=lambda value:{'tables':[],'snippets':[{'language':language,'text':value}],'rendered':''}
    examples[key]={'id':'teaching-'+key,'name':title,'kind':'sample','constructed':True,'paragraphs':[why,'Original constructed illustration, dedicated to the public domain under CC0. It explains the existing convention; it does not add a requirement.'],'sourceImages':[{'src':'/teaching-examples/'+file.name,'sha256':hashlib.sha256(svg.encode()).hexdigest(),'bytes':len(svg.encode())}],**out(expected),'bad':out(bad) if bad else None}
add('image-text','Text inside an image is still text',text(45,85,'Delivery notice',30)+text(45,145,'Arrives Wednsday at 09:30.')+text(45,195,'Gate B — keep this slip.'),'Delivery notice\n\nArrives Wednsday at 09:30.\n\nGate B — keep this slip.','Transcribe all visible text, including the printed typo “Wednsday”. Do not substitute an image link, a summary or a corrected spelling. The top line is a notice label, not a document section.','![Delivery notice](notice.png)')
table=rect(45,50,630,165)+line(45,105,675,105)+line(45,160,675,160)+line(405,50,405,215)+text(65,85,'Item')+text(430,85,'Count')+text(65,140,'Pencils')+text(430,140,'12')+text(65,195,'Pens')+text(430,195,'7')
tablemd='<table>\n<tr><th>Item</th><th>Count</th></tr>\n<tr><td>Pencils</td><td>12</td></tr>\n<tr><td>Pens</td><td>7</td></tr>\n</table>'
add('image-table','A pictured table stays a table',table,tablemd,'The image contains a two-column table. Preserve both rows and the printed headers; a prose summary loses the cell relationships.','A table listing stationery supplies.')
flow=rect(35,95,170,75,'#eff6ff')+rect(275,95,170,75,'#eff6ff')+rect(515,95,170,75,'#eff6ff')+text(64,140,'Receive',24)+text(305,140,'Review',24)+text(546,140,'Archive',24)
for x in [205,445]:flow+=line(x,132,x+70,132)+f'<path d="M{x+60} 125 L{x+70} 132 L{x+60} 139" fill="none" stroke="#334155" stroke-width="2"/>'
add('image-flow','A flow image becomes a diagram',flow,'```diagram/mermaid\nflowchart LR\n  A[Receive] --> B[Review]\n  B --> C[Archive]\n```','Keep all three printed labels and both directed connections. This simple flow fits Mermaid; other faithful supported diagram languages are valid.','[A three-step process diagram]')
art='<rect x="45" y="30" width="630" height="240" fill="#dbeafe"/><circle cx="555" cy="85" r="32" fill="#fbbf24"/><path d="M45 270 L225 65 L400 270 Z" fill="#64748b"/><path d="M245 270 L465 110 L675 270 Z" fill="#334155"/><path d="M195 100 L225 65 L255 100 Z" fill="white"/>'
add('image-art','Decorative artwork needs a description',art,'An illustration of two overlapping mountains beneath a yellow sun in a pale blue sky. The taller mountain on the left has a white peak.','There are no labels or data points to transcribe. Describe the visible artwork in prose without inventing a place, date or artist.','![Mountains](mountains.png)')
chart=text(45,40,'Orders',25)+line(100,65,100,235)+line(100,235,630,235)+rect(210,155,100,80,'#2563eb','none')+rect(420,75,100,160,'#2563eb','none')+text(248,145,'4')+text(458,65,'8')+text(227,270,'Apr')+text(436,270,'May')
add('image-chart','A chart image preserves its values',chart,'<table data-source="chart">\n<caption>Orders</caption>\n<tr><th>Month</th><th>Orders</th></tr>\n<tr><td>Apr</td><td>4</td></tr>\n<tr><td>May</td><td>8</td></tr>\n</table>','Use the printed values 4 and 8, not estimates from bar heights. Keep the title and month labels in the chart table.','Orders increased from April to May.')
add('equation','An equation inside a sentence',text(45,120,'The energy is E = mc',28)+text(306,107,'2',18)+text(322,120,'.',28),'The energy is $$E = mc^{2}$$.','This is mathematical notation, so encode the equation as LaTeX with double-dollar delimiters, even inside a sentence.','The energy is $E = mc^2$.')
add('bold-italic','Preserve bold and italic without inventing emphasis',text(45,100,'Urgent',28,'font-weight="bold"')+text(160,100,'review',28,'font-style="italic"')+text(260,100,'required.',28),'**Urgent** *review* required.','Only “Urgent” is bold and only “review” is italic. The rest stays plain.','**Urgent review required.**')
add('highlight','A yellow highlight has its own markup',text(45,105,'Bring')+rect(112,79,100,34,'yellow','none')+text(116,105,'photo ID')+text(225,105,'tomorrow.'),'Bring <mark style="background-color: yellow">photo ID</mark> tomorrow.','Preserve the yellow background as a highlight; it does not imply bold or meaningful yellow text.','Bring **photo ID** tomorrow.')
add('underline','Underline is not italic',text(45,110,'Return by Friday.')+line(45,116,230,116),'<u>Return by Friday.</u>','The entire printed sentence is underlined. Use the underline tag, not Markdown underscores.','_Return by Friday._')
add('super-sub','Raised references and lowered chemical indices',text(45,95,'Water: H')+text(141,103,'2',16)+text(151,95,'O')+text(45,160,'See note')+text(147,148,'3',16),'Water: H<sub>2</sub>O\n\nSee note<sup>3</sup>','These are non-mathematical raised and lowered characters. Keep them as tags, not Unicode substitutions.','Water: H₂O\n\nSee note³')
add('link','A printed URL is raw text by default',text(45,95,'Help:')+text(45,145,'https://example.org/help',26),'Help:\nhttps://example.org/help','No link extraction was requested. Transcribe the visible URL; do not infer a different target.','Help:\n[Support portal](https://example.org/help)')
add('quote','An inset quotation is ordinary text',line(55,65,55,205)+text(85,105,'“Measure twice,')+text(85,145,'cut once.”'),'“Measure twice,\ncut once.”','Preserve the quotation marks and printed line break. The inset styling does not authorize Markdown block-quote markers.','> “Measure twice,\n> cut once.”')
add('linebreak','Two printed lines form one block',text(45,100,'Please keep this receipt')+text(45,135,'until your order arrives.'),'Please keep this receipt\nuntil your order arrives.','This is one two-line block. Keep a plain newline, with no blank paragraph, trailing spaces or <br>.','Please keep this receipt<br>until your order arrives.')
add('separator','A printed divider is not a page boundary',text(45,70,'Morning session')+line(45,125,675,125)+text(45,185,'Afternoon session'),'Morning session\n\n<hr/>\n\nAfternoon session','Both labels are on one page with a visible divider. Use <hr/>; reserve --- for a change of page.','Morning session\n\n---\n\nAfternoon session')
add('header-only','Headers without a body are ordinary text',text(55,100,'Product')+text(325,100,'Quantity')+text(545,100,'Price')+line(45,120,675,120),'Product\nQuantity\nPrice','This is the complete available crop. No data rows or adjoining page are available. Preserve the labels without creating an empty table or inventing rows.','<table><tr><th>Product</th><th>Quantity</th><th>Price</th></tr></table>')
form=rect(35,45,650,190)+text(55,85,'1 Amount:')+text(230,85,'0012.50')+text(55,145,'2 Date:')+text(230,145,'03/04/26')+text(55,205,'3 Reference:')+line(235,210,625,210)
formmd='- \\[1\\] **Amount:** 0012.50\n- \\[2\\] **Date:** 03/04/26\n- \\[3\\] **Reference:** [blank]'
add('form-values','Keep values verbatim and blank fields explicit',form,formmd,'These are labeled fill-in fields, not a table. Keep leading zeros and the ambiguous date exactly as printed; do not infer a currency or expand the date. The third answer line is empty.','- **Amount:** $12.50\n- **Date:** March 4, 2026')
order=text(45,80,'1 Name: Ada')+text(390,80,'3 City: Dover')+text(45,170,'2 Code: 007')+text(390,170,'4 Zone: East')
add('form-order','Printed IDs override a row-wise scan',order,'- \\[1\\] **Name:** Ada\n- \\[2\\] **Code:** 007\n- \\[3\\] **City:** Dover\n- \\[4\\] **Zone:** East','Read fields 1, 2, 3, 4. A geometric left-to-right sweep across each row would incorrectly produce 1, 3, 2, 4.')
stamp=table+line(430,130,463,143)+text(475,141,'10',25,'font-style="italic" fill="#1d4ed8"')+text(480,265,'REVIEWED',22,'fill="#b91c1c"')
add('table-correction','A correction and a stamp play different roles',stamp,'<table>\n<tr><th>Item</th><th>Count</th></tr>\n<tr><td>Pencils</td><td>~~12~~ 10</td></tr>\n<tr><td>Pens</td><td>7</td></tr>\n</table>\n\nREVIEWED','The blue slanted “10” represents a handwritten correction to the struck 12. Retain both. The REVIEWED stamp is below the grid and stays outside the table. This is a schematic teaching illustration of handwriting.')
# Separate source images preserve true page boundaries, unlike a screenshot of two pages side by side.
add('document-page-one','Document structure continues across pages',text(35,35,'FIELD GUIDE',16)+text(45,95,'2 Maintenance',28,'font-weight="bold"')+text(45,155,'2.1 Inspection',24,'font-weight="bold"')+text(45,200,'Inspect daily.')+text(45,275,'Revision A · Page 4',16),'FIELD GUIDE\n\n## 2 Maintenance\n\n### 2.1 Inspection\n\nInspect daily.\n\nRevision A · Page 4\n\n---\n\nFIELD GUIDE\n\n### 2.2 Cleaning\n\nClean weekly.\n\nRevision A · Page 5','Two consecutive interior pages are shown in order. The document title is on an earlier cover; sections use level 2 and subsections level 3. The running header is plain text on both pages. The printed folios stay in their footer bands; they are not physical sheet indices.')
second=page(text(35,35,'FIELD GUIDE',16)+text(45,95,'2.2 Cleaning',24,'font-weight="bold"')+text(45,150,'Clean weekly.')+text(45,275,'Revision A · Page 5',16));(DEST/'document-page-two.svg').write_text(second)
examples['document-page-one']['sourceImages'].append({'src':'/teaching-examples/document-page-two.svg','sha256':hashlib.sha256(second.encode()).hexdigest(),'bytes':len(second.encode())})
add('cover','The cover title is not a recurring section',text(130,130,'FIELD GUIDE',42,'font-weight="bold"')+text(220,185,'Revision A',24),'# FIELD GUIDE\n\nRevision A','This is the cover of a paged document. Its title is a Title element. A matching running header on later interior pages is page furniture, not another Title.')
# Exact boxes use a deliberately simple source: one rectangular Picture element.
box=rect(120.5,80.5,239,119,'#dbeafe','#1d4ed8')
boxmd='<!-- el p=1 x=120 y=80 w=240 h=120 -->\nA pale blue rectangle with a blue outline.'
add('box','One picture, one element box',box,boxmd+'\n\nSidecar (separate JSON file):\n'+json.dumps({'pages':[{'page':1,'width':720,'height':300,'items':[{'type':'Picture','md':'A pale blue rectangle with a blue outline.','bBox':{'x':120,'y':80,'w':240,'h':120}}]}]},indent=2),'Element-level boxes were requested. The illustration is a single rectangular Picture region at x=120, y=80, width=240, height=120 in the 720×300 page coordinate space. The first block is the Markdown; the JSON below it is a separate sidecar, not extra document text.')
# Two equivalent encodings of genuinely blank spacer rows, applied consistently.
spacer=rect(45,40,630,210)+line(45,90,675,90)+line(45,140,675,140)+line(45,190,675,190)+line(405,40,405,250)+text(65,75,'Item')+text(430,75,'Count')+text(65,125,'Pencils')+text(430,125,'12')+text(65,230,'Pens')+text(430,230,'7')
spacemd='<table>\n<tr><th>Item</th><th>Count</th></tr>\n<tr><td>Pencils</td><td>12</td></tr>\n<tr><td></td><td></td></tr>\n<tr><td>Pens</td><td>7</td></tr>\n</table>'
add('spacer-alternatives','A real blank row admits two encodings',spacer,spacemd,'The empty ruled row is a purely decorative spacer, not the only boundary between groups. Keeping it (shown here) and omitting it both conform. Once chosen, use the same treatment for this situation throughout the document. The second snippet is the alternative output, not extra document content.')
examples['spacer-alternatives']['snippets'].append({'language':'markdown','text':tablemd})
# Keep the two deliverables separate in the viewer.
examples['box']['snippets']=[{'language':'markdown','text':boxmd},{'language':'json','text':json.dumps({'pages':[{'page':1,'width':720,'height':300,'items':[{'type':'Picture','md':'A pale blue rectangle with a blue outline.','bBox':{'x':120,'y':80,'w':240,'h':120}}]}]},indent=2)}]
# This mapping is editorial teaching material, separate from imported source/RFC examples.
groups={}
def use(slugs,ids,focus):
 for slug in slugs.split():groups[slug]={'examples':ids.split(),'focus':focus}
use('images-images images-images-and-figures','image-text image-table image-chart image-flow image-art equation','Classify the content inside the image, then encode that content. These constructed examples show different valid output forms and common information-losing substitutes.')
use('01-conventions-requirements-language 01-conventions-conformance 01-conventions-rule-status-and-scope','image-text image-table','Apply the focal MUST to a concrete output: an image link or summary loses content. Passing this one requirement does not establish whole-document conformance; status and scope still come from the rule badges.')
use('02-principles-the-page-is-the-ground-truth 02-principles-never-drop-never-invent','image-text header-only','Read only what is visible. Preserve a typo and refuse to fill in missing table rows from expectation.')
use('02-principles-traceability layout-annotation-granularity 03-output-model-the-sidecar','box','The requested granularity is element level. The picture has one region and one box. The Markdown anchor and separate sidecar refer to the same page coordinates.')
use('03-output-model-elements layout-block-annotation layout-layout-regions','image-table form-values image-flow','Similar rectangular regions can be tables, forms or pictures. Choose the class from the content and role before choosing the output syntax; these samples omit optional boxes.')
use('03-output-model-markdown-rendering','separator document-page-one','Contrast a printed line within one page with an actual page boundary between two source images.')
use('03-output-model-output-options','image-art document-page-one','These illustrate the narrower working default: describe graphics and retain printed folios in their bands. The rule remains open; these samples do not settle or add request options.')
use('04-document-level-document-rules page-structure-heading-depth-across-pages page-structure-recurring-page-furniture page-structure-printed-page-numbers','document-page-one','Both source pages belong to one document. Preserve the heading depth, classify repeated margin bands consistently, and keep each printed folio with its footer. Separate folio extraction is not requested in this example.')
use('04-document-level-document-type','cover document-page-one','Compare the cover with later interior pages of the same document. The repeated text FIELD GUIDE changes role: Title on the cover, Page-header in the interior.')
use('04-document-level-choices-made-once-per-document a-equivalent-forms-accepted-alternatives','spacer-alternatives','Both displayed encodings conform for this genuinely blank spacer row. Pick one treatment and apply it consistently wherever the same situation recurs in the document.')
use('page-structure-line-breaks-inside-a-block','linebreak','A source line break is not a new paragraph.')
use('page-structure-line-separators-and-breaks','separator document-page-one','The first sample has a divider on one page. The second has two source pages. They require different separators.')
use('07-text-text-formatting-conventions','bold-italic highlight underline super-sub equation','Compare visible glyph styles, background highlighting, raised/lowered text and mathematical notation. Each has its own encoding.')
for slug,key in [('bold-and-italics','bold-italic'),('highlighted-text','highlight'),('inline-equations','equation'),('links','link'),('quote-blocks','quote'),('superscript-and-subscript','super-sub'),('underlined-text','underline')]:
 use('text-1-inline-formatting-'+slug,key,'The source shows the printed appearance; the output shows the precise markup required by this convention.')
use('tables-1-what-counts-as-a-table-header-only-tables','header-only','The crop has no body and no joinable continuation. Do not manufacture a header-only HTML table.')
use('tables-6-cell-values-handwriting-and-stamps','table-correction','Preserve the old and replacement values together, while keeping a page-level stamp outside the table.')
use('forms-1-the-output-format-the-key-value-list forms-1-the-output-format-values-are-verbatim','form-values','Follow printed labels and IDs, preserve the exact values, and explicitly represent the empty field.')
use('forms-3-structure-form-reading-order','form-order','Follow the printed field sequence rather than the visual row order.')
use('c-producing-ground-truth-producing-ground-truth c-producing-ground-truth-about-the-examples','image-text image-table','Use these original constructed samples to practice reading the page before checking its expected encoding. They are teaching material, not evidence of a provider score.')
use('c-producing-ground-truth-ground-truth-charts charts-1-the-annotation-the-ground-truth-file','image-chart','This illustration shows the source and its Markdown target. The full reference below explains the separate annotation/test files; this teaching panel is not a substitute for those files.')
use('c-producing-ground-truth-ground-truth-headings-and-page-structure','document-page-one separator','Check the document context before assigning heading depth or confusing a printed divider with a page break.')
use('c-producing-ground-truth-ground-truth-images-diagrams-and-other','image-flow image-art','Decide whether a structured diagram language preserves the content or the image calls for a prose description.')
use('c-producing-ground-truth-ground-truth-inline-formatting','bold-italic highlight super-sub','Read the visible marks first, then compare the exact encoding. Do not infer emphasis from semantic importance.')
use('c-producing-ground-truth-ground-truth-layout','image-table form-values box','Classify the region before encoding it, and supply geometry at the requested granularity only.')
use('c-producing-ground-truth-ground-truth-lists-and-forms','form-values form-order','Keep values verbatim, encode empty fields and follow the form’s printed indexing.')
use('c-producing-ground-truth-ground-truth-marks-on-the-page','table-correction','Distinguish a value replacement from a stamp. Keep each in its correct structural position.')
use('c-producing-ground-truth-ground-truth-tables-1-3 c-producing-ground-truth-the-annotation-qa-checklist','image-table header-only','Compare a complete table with an isolated header. Verify the printed grid and available body before choosing an encoding.')
use('c-producing-ground-truth-ground-truth-tables-4-8','table-correction image-table','Inspect cell values and corrections without assigning a page-level mark to a table cell.')
use('d-quick-reference-quick-reference','image-text image-table image-flow form-values','A few representative source-to-output examples. The reference below lists the full set of rules; these panels do not replace it.')
from teaching_cases import extend
extend(add, text, rect, line, page, examples, groups, DEST)
(ROOT/'resources/convention-library/teaching-examples.json').write_text(json.dumps({'license':'CC0-1.0','provenance':'Original constructed illustrations authored for this guide; no third-party documents or customer data.','examples':examples,'conventions':groups},ensure_ascii=False,indent=2)+'\n')
print(f'{len(examples)} teaching examples, {len(groups)} convention/reference pages, {len(list(DEST.glob("*.svg")))} original SVGs')
